const HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Epochly \u2014 Unix Timestamp Converter & Discord Timestamp Generator</title>\n<meta name=\"description\" content=\"Epochly converts Unix timestamps to human-readable dates and back in seconds, milliseconds, microseconds and nanoseconds. Auto-detects units, batch-converts log timestamps, generates Discord <t:...> tags with live preview, and counts down to Y2K38. Free, unlimited, no signup.\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=JetBrains+Mono:ital,wght@0,400;0,500;0,700;0,800;1,400&display=swap\" rel=\"stylesheet\">\n<script src=\"https://cdn.tailwindcss.com\"></script>\n<script>\ntailwind.config = {\n  theme: {\n    extend: {\n      colors: { term: '#0B0F14', panel: '#10161D', phosphor: '#00E676', amberx: '#FFB300', dimline: '#1E2A36' },\n      fontFamily: { mono: ['\"JetBrains Mono\"','ui-monospace','SFMono-Regular','Menlo','Consolas','monospace'] }\n    }\n  }\n}\n</script>\n<style>\n  html { scroll-behavior: smooth; }\n  body { background:#0B0F14; }\n  .scanlines::after{content:\"\";position:fixed;inset:0;pointer-events:none;z-index:60;opacity:.05;\n    background:repeating-linear-gradient(0deg,#00E676 0 1px,transparent 1px 3px);}\n  .glow{text-shadow:0 0 18px rgba(0,230,118,.55),0 0 42px rgba(0,230,118,.25);}\n  .glow-amber{text-shadow:0 0 18px rgba(255,179,0,.5);}\n  .blink{animation:blink 1.1s steps(1) infinite;}\n  @keyframes blink{50%{opacity:0;}}\n  .term-panel{background:#10161D;border:1px solid #1E2A36;border-radius:.75rem;box-shadow:0 0 0 1px rgba(0,230,118,.04),0 12px 40px -18px rgba(0,230,118,.15);}\n  .term-panel:hover{border-color:rgba(0,230,118,.28);}\n  .prompt{color:#00E676;}\n  .tick{font-variant-numeric:tabular-nums;}\n  input,select,textarea{color-scheme:dark;}\n  .field{background:#0B0F14;border:1px solid #2A3A4A;border-radius:.5rem;color:#E2E8F0;}\n  .field:focus{outline:none;border-color:#00E676;box-shadow:0 0 0 3px rgba(0,230,118,.15);}\n  ::-webkit-scrollbar{width:10px;height:10px;}\n  ::-webkit-scrollbar-track{background:#0B0F14;}\n  ::-webkit-scrollbar-thumb{background:#1E2A36;border-radius:6px;border:2px solid #0B0F14;}\n  ::-webkit-scrollbar-thumb:hover{background:#00E676;}\n  .style-pill input{display:none;}\n  .style-pill span{display:inline-flex;align-items:center;gap:.35rem;padding:.4rem .7rem;border:1px solid #2A3A4A;border-radius:.5rem;cursor:pointer;font-size:.8rem;color:#94A3B8;transition:all .15s;}\n  .style-pill input:checked+span{border-color:#00E676;color:#00E676;background:rgba(0,230,118,.08);box-shadow:0 0 12px rgba(0,230,118,.2);}\n  .style-pill span:hover{border-color:#00E676;color:#E2E8F0;}\n  .seg-btn{padding:.35rem .9rem;border:1px solid #2A3A4A;font-size:.75rem;letter-spacing:.08em;color:#94A3B8;cursor:pointer;background:transparent;}\n  .seg-btn.active{background:rgba(0,230,118,.12);color:#00E676;border-color:#00E676;}\n  table.epoch-table{width:100%;border-collapse:collapse;font-size:.82rem;}\n  table.epoch-table th{text-align:left;padding:.6rem .75rem;color:#FFB300;font-weight:700;font-size:.7rem;letter-spacing:.12em;text-transform:uppercase;border-bottom:1px solid #2A3A4A;white-space:nowrap;}\n  table.epoch-table td{padding:.6rem .75rem;border-bottom:1px solid #16202B;color:#CBD5E1;vertical-align:top;}\n  table.epoch-table tr:last-child td{border-bottom:none;}\n  table.epoch-table tbody tr{transition:background .12s;}\n  table.epoch-table tbody tr:hover{background:rgba(0,230,118,.05);}\n  .copy-btn{font-size:.68rem;letter-spacing:.06em;padding:.28rem .6rem;border:1px solid #2A3A4A;border-radius:.375rem;color:#94A3B8;background:transparent;cursor:pointer;transition:all .15s;white-space:nowrap;}\n  .copy-btn:hover{border-color:#00E676;color:#00E676;}\n  .copy-btn.copied{border-color:#00E676;color:#00E676;background:rgba(0,230,118,.1);}\n  .faq-item{border:1px solid #1E2A36;border-radius:.6rem;background:#10161D;}\n  .faq-item summary{cursor:pointer;list-style:none;}\n  .faq-item summary::-webkit-details-marker{display:none;}\n  .article-body h2{color:#00E676;font-weight:800;font-size:1.35rem;margin:2.2rem 0 .8rem;letter-spacing:-.01em;}\n  .article-body h3{color:#FFB300;font-weight:700;font-size:1.05rem;margin:1.6rem 0 .6rem;}\n  .article-body p{color:#B6C2CF;line-height:1.8;margin-bottom:1rem;font-size:.95rem;}\n  .article-body ul,.article-body ol{color:#B6C2CF;line-height:1.8;margin:0 0 1rem 1.4rem;font-size:.95rem;}\n  .article-body li{margin-bottom:.4rem;}\n  .article-body code{background:#0B0F14;border:1px solid #2A3A4A;color:#00E676;padding:.1rem .4rem;border-radius:.3rem;font-size:.85em;}\n  .article-body strong{color:#E2E8F0;}\n  .discord-msg{background:#1E1F22;border-radius:.5rem;}\n</style>\n<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"FAQPage\",\n  \"mainEntity\": [\n    {\"@type\": \"Question\",\"name\": \"What is a Unix timestamp?\",\"acceptedAnswer\": {\"@type\": \"Answer\",\"text\": \"A Unix timestamp (also called epoch time or POSIX time) is the number of seconds that have elapsed since 00:00:00 UTC on 1 January 1970, not counting leap seconds. For example, 1700000000 corresponds to 14 November 2023. Timestamps are stored as plain integers, which makes them timezone-independent, compact, and easy to compare or sort \u2014 which is why APIs, databases, log files and file systems use them everywhere.\"}},\n    {\"@type\": \"Question\",\"name\": \"How do I know if my timestamp is in seconds or milliseconds?\",\"acceptedAnswer\": {\"@type\": \"Answer\",\"text\": \"Count the digits. A 10-digit number (like 1767225600) is seconds; 13 digits (like 1767225600000) is milliseconds; 16 digits is microseconds; 19 digits is nanoseconds. A quick sanity check: 10-digit values near 1.7\u20131.8 billion mean dates around 2024\u20132027. If your 13-digit value converts to a date in the year 50,000+, you treated milliseconds as seconds \u2014 divide by 1,000. Epochly auto-detects the unit from digit length so you rarely need to think about it.\"}},\n    {\"@type\": \"Question\",\"name\": \"How do I convert an epoch timestamp to a date?\",\"acceptedAnswer\": {\"@type\": \"Answer\",\"text\": \"Paste the timestamp into Epochly's converter and it is detected and converted instantly to UTC, your local time, and ISO 8601. Programmatically: in JavaScript use new Date(timestamp * 1000) for seconds or new Date(timestamp) for milliseconds; in Python use datetime.fromtimestamp(ts, tz=timezone.utc); in most SQL dialects use FROM_UNIXTIME(ts). Always confirm whether your value is seconds or milliseconds first \u2014 that is the single most common conversion mistake.\"}},\n    {\"@type\": \"Question\",\"name\": \"How do Discord timestamp tags work?\",\"acceptedAnswer\": {\"@type\": \"Answer\",\"text\": \"Discord renders <t:UNIX_TIMESTAMP:STYLE> tags as dates in each viewer's own timezone. Replace UNIX_TIMESTAMP with epoch seconds and STYLE with one of t (short time), T (long time), d (short date), D (long date), f (short date/time, the default), F (long date/time) or R (relative, e.g. '2 hours ago'). Epochly's Discord generator builds the tag and shows a live preview of exactly how it will look for every style.\"}},\n    {\"@type\": \"Question\",\"name\": \"What is the Y2K38 problem?\",\"acceptedAnswer\": {\"@type\": \"Answer\",\"text\": \"Many older systems store Unix time in a signed 32-bit integer, whose maximum value is 2,147,483,647 \u2014 corresponding to 03:14:07 UTC on 19 January 2038. One second later the counter overflows to a negative number and dates jump back to 1901. Modern 64-bit systems are unaffected, but embedded devices, old databases and legacy file formats may still break. Epochly includes a live countdown to the Y2K38 rollover so you can watch it approach.\"}},\n    {\"@type\": \"Question\",\"name\": \"Why is my converted timestamp off by a few hours?\",\"acceptedAnswer\": {\"@type\": \"Answer\",\"text\": \"Almost always a timezone issue. Unix timestamps are defined in UTC, but many tools display the result in your computer's local timezone. A 5-hour-30-minute offset for a user in India (IST = UTC+5:30) is expected and correct \u2014 the timestamp itself is fine. Compare the UTC output rather than the local one when debugging, and make sure date inputs are interpreted in the timezone you intend (Epochly lets you choose UTC or local when converting dates to timestamps). Daylight-saving transitions can add a further one-hour surprise twice a year.\"}}\n  ]\n}\n</script>\n</head>\n<body id=\"top\" class=\"scanlines bg-term text-slate-200 font-mono antialiased\">\n\n<!-- ============ STICKY HEADER ============ -->\n<header class=\"sticky top-0 z-50 bg-term/95 backdrop-blur border-b border-phosphor/20\">\n  <div class=\"mx-auto max-w-6xl px-4 sm:px-6 h-16 flex items-center justify-between\">\n    <a href=\"#top\" class=\"text-xl sm:text-2xl font-extrabold tracking-tight text-phosphor glow\">Epochly<span class=\"text-amberx blink\">_</span></a>\n    <nav class=\"flex items-center gap-5 sm:gap-8 text-sm\">\n      <a href=\"#top\" class=\"text-slate-300 hover:text-phosphor transition-colors\">Home</a>\n      <a href=\"https://fixoraa.tech\" class=\"text-slate-300 hover:text-phosphor transition-colors\">More Tools</a>\n    </nav>\n  </div>\n</header>\n\n<!-- ============ LIVE CLOCK HERO ============ -->\n<section class=\"mx-auto max-w-6xl px-4 sm:px-6 pt-10 pb-6 text-center\">\n  <p class=\"text-xs sm:text-sm text-slate-500 mb-3\"><span class=\"prompt\">$</span> date +%s <span class=\"text-slate-600\"># \u2014 the current Unix timestamp, ticking live</span></p>\n  <div id=\"hero-seconds\" class=\"tick text-phosphor glow font-extrabold tracking-tight leading-none text-[13vw] sm:text-7xl md:text-8xl select-all\">\u2014</div>\n  <div class=\"mt-4 flex flex-wrap items-center justify-center gap-x-8 gap-y-2 text-xs sm:text-sm text-slate-400\">\n    <span>ms <span id=\"hero-ms\" class=\"tick text-slate-200\">\u2014</span></span>\n    <span>UTC <span id=\"hero-utc\" class=\"tick text-slate-200\">\u2014</span></span>\n    <span>local <span id=\"hero-local\" class=\"tick text-slate-200\">\u2014</span></span>\n  </div>\n  <div class=\"mt-5 flex items-center justify-center gap-3\">\n    <button data-copy-target=\"hero-seconds\" class=\"copy-btn\">COPY SECONDS</button>\n    <button data-copy-target=\"hero-ms\" class=\"copy-btn\">COPY MS</button>\n  </div>\n</section>\n\n<!-- TOP AD (verbatim) -->\n<div class=\"no-print mx-auto max-w-6xl px-4 sm:px-6 pt-4\" role=\"complementary\" aria-label=\"Advertisement\">\n  <div class=\"mx-auto text-center\" style=\"max-width:728px\">\n    <span class=\"block text-[10px] tracking-[0.18em] uppercase text-slate-400 mb-1.5\">Advertisement</span>\n    <div class=\"flex justify-center overflow-hidden\">\n      <div class=\"origin-top scale-[0.44] sm:scale-100 shrink-0\">\n        <script>\n          atOptions = { 'key' : '4e68ac77881c17fe128a46565d9a4e8c', 'format' : 'iframe', 'height' : 90, 'width' : 728, 'params' : {} };\n        </script>\n        <script src=\"https://www.highrevenueformat.com/4e68ac77881c17fe128a46565d9a4e8c/invoke.js\"></script>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ============ TOOL ============ -->\n<main class=\"mx-auto max-w-6xl px-4 sm:px-6 py-8\">\n\n  <div class=\"flex flex-wrap items-center justify-between gap-3 mb-6\">\n    <h1 class=\"text-2xl sm:text-3xl font-extrabold text-slate-100\"><span class=\"prompt\">&gt;_</span> Timestamp <span class=\"text-phosphor\">Console</span></h1>\n    <span class=\"inline-flex items-center gap-2 text-[11px] font-bold tracking-[0.14em] uppercase text-phosphor border border-phosphor/50 rounded-full px-4 py-1.5 bg-phosphor/5\">\n      <span class=\"w-2 h-2 rounded-full bg-phosphor blink\"></span> Unlimited Free Usage\n    </span>\n  </div>\n  <p class=\"text-slate-400 text-sm mb-8 max-w-3xl\">Bidirectional epoch converter with automatic unit detection, batch log conversion, a Discord <span class=\"text-phosphor\">&lt;t:\u2026&gt;</span> tag studio, and a live Y2K38 countdown. No signup, no paywall, no watermark \u2014 everything runs in your browser.</p>\n\n  <!-- ===== BIDIRECTIONAL CONVERSION PANES ===== -->\n  <div class=\"grid lg:grid-cols-2 gap-6 mb-6\">\n\n    <!-- Pane A: timestamp -> date -->\n    <section class=\"term-panel p-5 sm:p-6\" aria-label=\"Timestamp to date converter\">\n      <div class=\"flex items-center justify-between mb-1\">\n        <h2 class=\"text-lg font-bold text-slate-100\"><span class=\"prompt\">$</span> epoch <span class=\"text-slate-500\">\u2192</span> date</h2>\n        <span id=\"unit-badge\" class=\"text-[11px] font-bold tracking-wider uppercase px-2.5 py-1 rounded border border-amberx/60 text-amberx glow-amber\">auto: \u2014</span>\n      </div>\n      <p class=\"text-xs text-slate-500 mb-4\">Paste any timestamp \u2014 seconds, ms, \u00b5s or ns are auto-detected by digit length.</p>\n      <div class=\"flex flex-col sm:flex-row gap-3 mb-4\">\n        <input id=\"ts-input\" type=\"text\" inputmode=\"numeric\" placeholder=\"e.g. 1767225600 or 1767225600000\"\n               class=\"field flex-1 px-4 py-3 text-base tick\" autocomplete=\"off\" spellcheck=\"false\">\n        <select id=\"unit-override\" class=\"field px-3 py-3 text-sm sm:w-40\" aria-label=\"Unit override\">\n          <option value=\"auto\">Auto-detect</option>\n          <option value=\"s\">Seconds</option>\n          <option value=\"ms\">Milliseconds</option>\n          <option value=\"us\">Microseconds</option>\n          <option value=\"ns\">Nanoseconds</option>\n        </select>\n      </div>\n      <div class=\"flex flex-wrap gap-2 mb-4\">\n        <button id=\"ts-convert\" class=\"px-5 py-2.5 bg-phosphor text-term font-bold text-sm rounded-md hover:brightness-110 active:scale-95 transition\">CONVERT</button>\n        <button id=\"ts-now\" class=\"copy-btn !py-2.5 !px-4\">USE NOW</button>\n        <button id=\"ts-clear\" class=\"copy-btn !py-2.5 !px-4\">CLEAR</button>\n      </div>\n      <div id=\"ts-error\" class=\"hidden text-sm text-red-400 border border-red-400/40 bg-red-400/5 rounded-md px-3 py-2 mb-4\"></div>\n      <dl id=\"ts-results\" class=\"space-y-2.5 text-sm opacity-40\">\n        <div class=\"flex items-start justify-between gap-3\"><dt class=\"text-slate-500 shrink-0 w-24\">UTC</dt><dd id=\"r-utc\" class=\"tick text-slate-200 text-right break-all\">\u2014</dd></div>\n        <div class=\"flex items-start justify-between gap-3\"><dt class=\"text-slate-500 shrink-0 w-24\">Local <span class=\"text-slate-600\">(you)</span></dt><dd id=\"r-local\" class=\"tick text-slate-200 text-right break-all\">\u2014</dd></div>\n        <div class=\"flex items-start justify-between gap-3\"><dt class=\"text-slate-500 shrink-0 w-24\">ISO 8601</dt><dd id=\"r-iso\" class=\"tick text-slate-200 text-right break-all select-all\">\u2014</dd></div>\n        <div class=\"flex items-start justify-between gap-3\"><dt class=\"text-slate-500 shrink-0 w-24\">Relative</dt><dd id=\"r-rel\" class=\"text-amberx text-right\">\u2014</dd></div>\n        <div class=\"flex items-start justify-between gap-3\"><dt class=\"text-slate-500 shrink-0 w-24\">Day</dt><dd id=\"r-day\" class=\"text-slate-200 text-right\">\u2014</dd></div>\n      </dl>\n      <div class=\"mt-4 flex gap-2\">\n        <button data-copy-target=\"r-iso\" class=\"copy-btn\">COPY ISO</button>\n        <button data-copy-target=\"r-utc\" class=\"copy-btn\">COPY UTC</button>\n      </div>\n    </section>\n\n    <!-- Pane B: date -> timestamp -->\n    <section class=\"term-panel p-5 sm:p-6\" aria-label=\"Date to timestamp converter\">\n      <h2 class=\"text-lg font-bold text-slate-100 mb-1\"><span class=\"prompt\">$</span> date <span class=\"text-slate-500\">\u2192</span> epoch</h2>\n      <p class=\"text-xs text-slate-500 mb-4\">Pick a date &amp; time, choose how to interpret it, get all four units.</p>\n      <input id=\"dt-input\" type=\"datetime-local\" step=\"1\" class=\"field w-full px-4 py-3 text-base mb-3\">\n      <div class=\"flex items-center gap-3 mb-4 text-xs text-slate-400\">\n        <span class=\"text-slate-500\">Interpret input as:</span>\n        <div class=\"flex rounded-md overflow-hidden border border-dimline\">\n          <button id=\"tz-local\" class=\"seg-btn active\">LOCAL</button>\n          <button id=\"tz-utc\" class=\"seg-btn\">UTC</button>\n        </div>\n      </div>\n      <div class=\"flex flex-wrap gap-2 mb-4\">\n        <button id=\"dt-convert\" class=\"px-5 py-2.5 bg-phosphor text-term font-bold text-sm rounded-md hover:brightness-110 active:scale-95 transition\">CONVERT</button>\n        <button id=\"dt-now\" class=\"copy-btn !py-2.5 !px-4\">USE NOW</button>\n      </div>\n      <div id=\"dt-error\" class=\"hidden text-sm text-red-400 border border-red-400/40 bg-red-400/5 rounded-md px-3 py-2 mb-4\"></div>\n      <dl id=\"dt-results\" class=\"space-y-2.5 text-sm opacity-40\">\n        <div class=\"flex items-center justify-between gap-3\"><dt class=\"text-slate-500\">Seconds <span class=\"text-slate-600\">(10-digit)</span></dt><dd class=\"flex items-center gap-2\"><code id=\"o-s\" class=\"tick text-phosphor select-all\">\u2014</code><button data-copy-target=\"o-s\" class=\"copy-btn\">COPY</button></dd></div>\n        <div class=\"flex items-center justify-between gap-3\"><dt class=\"text-slate-500\">Milliseconds <span class=\"text-slate-600\">(13-digit)</span></dt><dd class=\"flex items-center gap-2\"><code id=\"o-ms\" class=\"tick text-phosphor select-all\">\u2014</code><button data-copy-target=\"o-ms\" class=\"copy-btn\">COPY</button></dd></div>\n        <div class=\"flex items-center justify-between gap-3\"><dt class=\"text-slate-500\">Microseconds <span class=\"text-slate-600\">(16-digit)</span></dt><dd class=\"flex items-center gap-2\"><code id=\"o-us\" class=\"tick text-phosphor select-all break-all text-right\">\u2014</code><button data-copy-target=\"o-us\" class=\"copy-btn\">COPY</button></dd></div>\n        <div class=\"flex items-center justify-between gap-3\"><dt class=\"text-slate-500\">Nanoseconds <span class=\"text-slate-600\">(19-digit)</span></dt><dd class=\"flex items-center gap-2\"><code id=\"o-ns\" class=\"tick text-phosphor select-all break-all text-right\">\u2014</code><button data-copy-target=\"o-ns\" class=\"copy-btn\">COPY</button></dd></div>\n      </dl>\n    </section>\n  </div>\n\n  <!-- ===== BATCH MODE ===== -->\n  <section class=\"term-panel p-5 sm:p-6 mb-6\" aria-label=\"Batch timestamp converter\">\n    <div class=\"flex flex-wrap items-center justify-between gap-3 mb-1\">\n      <h2 class=\"text-lg font-bold text-slate-100\"><span class=\"prompt\">$</span> batch <span class=\"text-slate-500\">--logs</span></h2>\n      <span class=\"text-[11px] text-slate-500\">one timestamp per line \u00b7 units auto-detected per line</span>\n    </div>\n    <p class=\"text-xs text-slate-500 mb-4\">Paste server logs or a column of epoch values \u2014 every line is converted to a readable UTC row.</p>\n    <textarea id=\"batch-input\" rows=\"5\" placeholder=\"1767225600&#10;1767225600000&#10;1699999999123456&#10;1699999999123456789\"\n              class=\"field w-full px-4 py-3 text-sm tick mb-3\" spellcheck=\"false\"></textarea>\n    <div class=\"flex flex-wrap gap-2 mb-4\">\n      <button id=\"batch-run\" class=\"px-5 py-2.5 bg-phosphor text-term font-bold text-sm rounded-md hover:brightness-110 active:scale-95 transition\">CONVERT ALL</button>\n      <button id=\"batch-sample\" class=\"copy-btn !py-2.5 !px-4\">LOAD SAMPLE</button>\n      <button id=\"batch-clear\" class=\"copy-btn !py-2.5 !px-4\">CLEAR</button>\n      <button id=\"batch-copy\" class=\"copy-btn !py-2.5 !px-4 hidden\">COPY TABLE</button>\n    </div>\n    <div id=\"batch-error\" class=\"hidden text-sm text-red-400 border border-red-400/40 bg-red-400/5 rounded-md px-3 py-2 mb-4\"></div>\n    <div class=\"overflow-x-auto rounded-md border border-dimline\">\n      <table class=\"epoch-table\" id=\"batch-table\">\n        <thead><tr><th>#</th><th>Input</th><th>Unit</th><th>UTC date</th><th>ISO 8601</th></tr></thead>\n        <tbody id=\"batch-body\"><tr><td colspan=\"5\" class=\"!text-slate-600 !text-center py-6\">No rows yet \u2014 paste timestamps above and hit CONVERT ALL.</td></tr></tbody>\n      </table>\n    </div>\n  </section>\n\n  <!-- ===== DISCORD TIMESTAMP STUDIO ===== -->\n  <section class=\"term-panel p-5 sm:p-6 mb-6\" aria-label=\"Discord timestamp generator\">\n    <div class=\"flex flex-wrap items-center justify-between gap-3 mb-1\">\n      <h2 class=\"text-lg font-bold text-slate-100\"><span class=\"prompt\">$</span> discord <span class=\"text-slate-500\">--tag</span></h2>\n      <span class=\"text-[11px] text-slate-500\">renders in each viewer's own timezone on Discord</span>\n    </div>\n    <p class=\"text-xs text-slate-500 mb-4\">Pick a moment, choose a style \u2014 copy the <span class=\"text-phosphor\">&lt;t:\u2026&gt;</span> tag straight into any Discord message.</p>\n    <div class=\"grid md:grid-cols-2 gap-6\">\n      <div>\n        <div class=\"flex flex-col sm:flex-row gap-3 mb-4\">\n          <input id=\"dc-input\" type=\"datetime-local\" step=\"1\" class=\"field flex-1 px-4 py-3 text-base\">\n          <button id=\"dc-now\" class=\"copy-btn !py-3 !px-4 shrink-0\">NOW</button>\n        </div>\n        <div class=\"flex flex-wrap gap-2 mb-4\" role=\"radiogroup\" aria-label=\"Discord timestamp style\">\n          <label class=\"style-pill\"><input type=\"radio\" name=\"dc-style\" value=\"t\"><span><b class=\"text-phosphor\">t</b> short time</span></label>\n          <label class=\"style-pill\"><input type=\"radio\" name=\"dc-style\" value=\"T\"><span><b class=\"text-phosphor\">T</b> long time</span></label>\n          <label class=\"style-pill\"><input type=\"radio\" name=\"dc-style\" value=\"d\"><span><b class=\"text-phosphor\">d</b> short date</span></label>\n          <label class=\"style-pill\"><input type=\"radio\" name=\"dc-style\" value=\"D\"><span><b class=\"text-phosphor\">D</b> long date</span></label>\n          <label class=\"style-pill\"><input type=\"radio\" name=\"dc-style\" value=\"f\" checked><span><b class=\"text-phosphor\">f</b> short date/time</span></label>\n          <label class=\"style-pill\"><input type=\"radio\" name=\"dc-style\" value=\"F\"><span><b class=\"text-phosphor\">F</b> long date/time</span></label>\n          <label class=\"style-pill\"><input type=\"radio\" name=\"dc-style\" value=\"R\"><span><b class=\"text-amberx\">R</b> relative</span></label>\n        </div>\n        <div class=\"bg-term border border-dimline rounded-md p-4 mb-3\">\n          <p class=\"text-[10px] tracking-[0.18em] uppercase text-slate-500 mb-2\">Generated tag</p>\n          <code id=\"dc-tag\" class=\"tick text-phosphor text-base sm:text-lg break-all select-all\">&lt;t:\u2026:f&gt;</code>\n        </div>\n        <button id=\"dc-copy\" class=\"px-5 py-2.5 bg-amberx text-term font-bold text-sm rounded-md hover:brightness-110 active:scale-95 transition\">COPY DISCORD TAG</button>\n        <div id=\"dc-error\" class=\"hidden mt-3 text-sm text-red-400 border border-red-400/40 bg-red-400/5 rounded-md px-3 py-2\"></div>\n      </div>\n      <div>\n        <p class=\"text-[10px] tracking-[0.18em] uppercase text-slate-500 mb-2\">Live preview <span class=\"normal-case tracking-normal\">(as Discord would render it)</span></p>\n        <div class=\"discord-msg p-4\">\n          <div class=\"flex gap-3\">\n            <div class=\"w-10 h-10 rounded-full bg-phosphor/20 border border-phosphor/40 flex items-center justify-center text-phosphor font-bold shrink-0\">E</div>\n            <div class=\"min-w-0\">\n              <p class=\"text-sm\"><span class=\"text-phosphor font-semibold\">Epochly Bot</span> <span class=\"text-[10px] bg-phosphor/20 text-phosphor px-1.5 py-0.5 rounded ml-1 align-middle\">BOT</span> <span id=\"dc-preview-time\" class=\"text-xs text-slate-500 ml-1\">today</span></p>\n              <p class=\"text-[15px] text-slate-200 mt-0.5\">The event starts <span id=\"dc-preview\" class=\"bg-phosphor/15 text-phosphor px-1 rounded font-medium\">\u2014</span></p>\n            </div>\n          </div>\n        </div>\n        <div class=\"mt-3 text-xs text-slate-500 leading-relaxed\">\n          <p class=\"mb-1 text-slate-400 font-bold\">All 7 styles, same moment:</p>\n          <div id=\"dc-all-styles\" class=\"grid grid-cols-1 sm:grid-cols-2 gap-x-4 gap-y-1 tick\"></div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ===== Y2K38 + FAMOUS EPOCHS ===== -->\n  <div class=\"grid lg:grid-cols-5 gap-6 mb-2\">\n    <section class=\"term-panel p-5 sm:p-6 lg:col-span-2\" aria-label=\"Y2K38 countdown\">\n      <h2 class=\"text-lg font-bold text-slate-100 mb-1\"><span class=\"prompt\">$</span> y2k38 <span class=\"text-slate-500\">--countdown</span></h2>\n      <p class=\"text-xs text-slate-500 mb-4\">Signed 32-bit time ends at <code class=\"text-amberx\">2147483647</code><br>\u2192 2038-01-19 03:14:07 UTC</p>\n      <div class=\"grid grid-cols-4 gap-2 text-center mb-4\">\n        <div class=\"bg-term border border-dimline rounded-md py-3\"><div id=\"cd-d\" class=\"tick text-2xl sm:text-3xl font-extrabold text-amberx glow-amber\">\u2014</div><div class=\"text-[10px] tracking-[0.18em] text-slate-500 mt-1\">DAYS</div></div>\n        <div class=\"bg-term border border-dimline rounded-md py-3\"><div id=\"cd-h\" class=\"tick text-2xl sm:text-3xl font-extrabold text-amberx glow-amber\">\u2014</div><div class=\"text-[10px] tracking-[0.18em] text-slate-500 mt-1\">HOURS</div></div>\n        <div class=\"bg-term border border-dimline rounded-md py-3\"><div id=\"cd-m\" class=\"tick text-2xl sm:text-3xl font-extrabold text-amberx glow-amber\">\u2014</div><div class=\"text-[10px] tracking-[0.18em] text-slate-500 mt-1\">MIN</div></div>\n        <div class=\"bg-term border border-dimline rounded-md py-3\"><div id=\"cd-s\" class=\"tick text-2xl sm:text-3xl font-extrabold text-amberx glow-amber\">\u2014</div><div class=\"text-[10px] tracking-[0.18em] text-slate-500 mt-1\">SEC</div></div>\n      </div>\n      <div class=\"h-2 rounded-full bg-term border border-dimline overflow-hidden mb-2\">\n        <div id=\"cd-bar\" class=\"h-full bg-gradient-to-r from-phosphor to-amberx rounded-full\" style=\"width:0%\"></div>\n      </div>\n      <p class=\"text-[11px] text-slate-500\"><span id=\"cd-pct\" class=\"text-slate-300 tick\">\u2014</span> of the 32-bit era elapsed since 1970</p>\n    </section>\n\n    <section class=\"term-panel p-5 sm:p-6 lg:col-span-3\" aria-label=\"Famous epochs reference\">\n      <div class=\"flex flex-wrap items-center justify-between gap-2 mb-1\">\n        <h2 class=\"text-lg font-bold text-slate-100\"><span class=\"prompt\">$</span> epochs <span class=\"text-slate-500\">--famous</span></h2>\n        <span class=\"text-[11px] text-slate-500\">click a row to load it into the converter</span>\n      </div>\n      <div class=\"overflow-x-auto\">\n        <table class=\"epoch-table\">\n          <thead><tr><th>Timestamp</th><th>UTC date</th><th>Event</th></tr></thead>\n          <tbody id=\"famous-body\"></tbody>\n        </table>\n      </div>\n    </section>\n  </div>\n\n</main>\n\n<!-- BOTTOM AD (verbatim) -->\n<div class=\"no-print mx-auto max-w-6xl px-4 sm:px-6 pb-4\" role=\"complementary\" aria-label=\"Advertisement\">\n  <div class=\"mx-auto text-center\" style=\"max-width:728px\">\n    <span class=\"block text-[10px] tracking-[0.18em] uppercase text-slate-400 mb-1.5\">Advertisement</span>\n    <div class=\"flex justify-center overflow-hidden\">\n      <script async src=\"https://js.wpadmngr.com/static/adManager.js\" data-admpid=\"464498\"></script>\n    </div>\n  </div>\n</div>\n\n<!-- ============ SEO ARTICLE + FAQS ============ -->\n<section class=\"mx-auto max-w-6xl px-4 sm:px-6 pb-10\">\n  <article id=\"seo-article\" class=\"article-body term-panel p-5 sm:p-8\">\n    <p class=\"text-[11px] tracking-[0.2em] uppercase text-amberx mb-2\">// knowledge base</p>\n    <h1 class=\"!text-phosphor !text-2xl sm:!text-3xl font-extrabold mb-4 mt-0\" style=\"margin-top:0\">Unix Timestamps: The Complete Guide to Epoch Time</h1>\n\n    <h2>What is a Unix timestamp?</h2>\n    <p>A <strong>Unix timestamp</strong> \u2014 also called <strong>epoch time</strong> or <strong>POSIX time</strong> \u2014 is the number of seconds that have elapsed since <strong>00:00:00 UTC on 1 January 1970</strong>, a moment known as the <strong>Unix epoch</strong>. It is stored as a plain integer, with no timezone, no formatting, and no ambiguity. For example, <code>1767225600</code> always means the same instant everywhere on Earth: midnight UTC on 1 January 2026.</p>\n    <p>This simplicity is exactly why timestamps dominate computing. Comparing two moments is a single integer comparison. Sorting events is a numeric sort. Storing a date costs 4\u20138 bytes instead of a 25-character string. APIs, databases, log files, file systems, JWT tokens, and caching headers all speak epoch time because it removes an entire category of parsing bugs. When you see a 10-digit number like <code>1700000000</code> in a JSON response, you are looking at 14 November 2023 \u2014 and a converter like the one above turns it into a human date in one step.</p>\n\n    <h2>Why 1 January 1970?</h2>\n    <p>The date was chosen by the engineers building Unix at Bell Labs in the early 1970s. They needed a convenient round starting point for timekeeping, and 1 January 1970 was recent enough that 32-bit counters would last decades, yet early enough to cover the useful history of computing. The choice stuck: the C standard library, POSIX, and eventually nearly every operating system and programming language adopted the same origin. Today the epoch is baked into JavaScript's <code>Date</code>, Python's <code>time</code> module, Java's <code>Instant</code>, Go's <code>time.Unix</code>, and SQL functions like <code>FROM_UNIXTIME()</code>. Changing it now would break the world, so 1970-01-01 is effectively permanent.</p>\n\n    <h2>Seconds, milliseconds, microseconds, nanoseconds</h2>\n    <p>The original definition counts <strong>seconds</strong>, producing 10-digit values (currently around 1.78 billion). But modern systems often need finer precision, so the same epoch is also counted in smaller units:</p>\n    <ul>\n      <li><strong>Seconds (s)</strong> \u2014 10 digits, e.g. <code>1767225600</code>. The classic Unix timestamp. Used by PHP's <code>time()</code>, Python's <code>time.time()</code>, and most REST APIs.</li>\n      <li><strong>Milliseconds (ms)</strong> \u2014 13 digits, e.g. <code>1767225600000</code>. JavaScript's <code>Date.now()</code> returns this, so web developers meet it constantly.</li>\n      <li><strong>Microseconds (\u00b5s)</strong> \u2014 16 digits, e.g. <code>1767225600000000</code>. Common in databases (MySQL <code>DATETIME(6)</code>), PHP's <code>microtime(true)</code>, and high-frequency trading logs.</li>\n      <li><strong>Nanoseconds (ns)</strong> \u2014 19 digits, e.g. <code>1767225600000000000</code>. Used by Go, Java's <code>System.nanoTime</code>-adjacent APIs, and Linux's <code>clock_gettime</code>.</li>\n    </ul>\n    <p>The digit-length rule is the fastest way to identify a unit: <strong>10 \u2192 seconds, 13 \u2192 milliseconds, 16 \u2192 microseconds, 19 \u2192 nanoseconds</strong>. Epochly applies exactly this heuristic automatically, so you can paste any of the four without selecting anything. The most common bug in timestamp work is mixing seconds and milliseconds \u2014 if your date lands in the year 55,000, divide by 1,000; if it lands in 1970, multiply by 1,000.</p>\n\n    <h2>How to convert a timestamp to a date (and back)</h2>\n    <p>Converting <strong>epoch to date</strong> is a division problem; converting <strong>date to epoch</strong> is about pinning a calendar moment to the UTC timeline. In JavaScript: <code>new Date(1767225600 * 1000)</code> for seconds, or <code>new Date(1767225600000)</code> for milliseconds. In Python: <code>datetime.fromtimestamp(1767225600, tz=timezone.utc)</code>. In a terminal: <code>date -d @1767225600 -u</code> on Linux. Going the other way, JavaScript's <code>Math.floor(date.getTime() / 1000)</code> gives epoch seconds, and Python's <code>int(dt.timestamp())</code> does the same.</p>\n    <p>Two details matter. First, confirm the unit before converting \u2014 the digit rule above. Second, decide which timezone the <em>displayed</em> result should use. The timestamp itself is always UTC; only its rendering changes. Epochly shows UTC, your local time, ISO 8601, the weekday, and a relative phrase (\"3 days ago\") side by side so nothing is left ambiguous.</p>\n\n    <h2>The timezone trap (and how to avoid it)</h2>\n    <p>Nine out of ten \"my timestamp is wrong\" reports are timezone confusion, not bad data. A Unix timestamp has no timezone \u2014 it is a single point on the global timeline. The confusion appears when software <em>displays</em> it: midnight UTC on 1 January 2026 is still 31 December 2025 in New York and already morning in Tokyo. If your conversion is off by exactly your UTC offset (5:30 for India, 5:00 for US Eastern in winter), the timestamp is fine and the display timezone is the culprit.</p>\n    <p>Defensive habits: store and transmit timestamps in UTC always; convert to local time only at the final display step; when debugging, compare the UTC rendering, not the local one; and remember daylight-saving shifts can inject a one-hour surprise twice a year in regions that observe it. When Epochly converts a date <em>to</em> a timestamp, it lets you declare whether the input means local time or UTC \u2014 that single toggle eliminates the most common direction of the bug.</p>\n\n    <h2>Y2K38: the 2038 problem</h2>\n    <p>Systems that store Unix time in a <strong>signed 32-bit integer</strong> hit a wall at <code>2147483647</code> \u2014 03:14:07 UTC on <strong>19 January 2038</strong>. One second later the counter overflows into negative numbers and clocks jump back to December 1901. It is the same class of bug as Y2K, but harder to fix because the vulnerable counters hide in embedded controllers, old file formats, legacy databases, and binary network protocols rather than in visible date fields.</p>\n    <p>Modern 64-bit operating systems, languages, and databases already use 64-bit time and are safe for billions of years. The risk sits in long-lived infrastructure: industrial controllers, automotive firmware, medical devices, and archived data formats designed decades ago. If you maintain such systems, audit every place a 32-bit <code>time_t</code> or 32-bit timestamp column appears, and migrate storage to 64-bit integers well before 2038. The live countdown above shows exactly how much runway remains.</p>\n\n    <h3>Famous epoch milestones</h3>\n    <p>Certain timestamps have become landmarks: <code>0</code> (the epoch itself, 1970-01-01), <code>1000000000</code> (the billion-second party, 2001-09-09), <code>1234567890</code> (2009-02-13), <code>1500000000</code> (2017-07-14), <code>2000000000</code> (2033-05-18), and <code>2147483647</code> (the 32-bit limit). Developers use them as test fixtures and Easter eggs; the reference table above renders each one and loads it into the converter on click.</p>\n\n    <h2>Discord timestamps: dynamic dates for every viewer</h2>\n    <p>Discord supports a special syntax \u2014 <code>&lt;t:UNIX_TIMESTAMP:STYLE&gt;</code> \u2014 that renders as a date <strong>in each reader's own timezone</strong>. Post <code>&lt;t:1767225600:F&gt;</code> and an American sees \"Wednesday, December 31, 2025 7:00 PM\" while an Indian sees \"Thursday, January 1, 2026 5:30 AM\", both correct. It is the cleanest way to announce event times to a global audience.</p>\n    <p>All seven styles: <code>t</code> short time (4:20 PM), <code>T</code> long time (4:20:30 PM), <code>d</code> short date (1/1/2026), <code>D</code> long date (January 1, 2026), <code>f</code> short date/time (the default when no style is given), <code>F</code> full date/time with weekday, and <code>R</code> relative (\"in 3 days\" / \"2 hours ago\" \u2014 it even updates live on Discord). The timestamp must be whole <strong>seconds</strong>, not milliseconds. Epochly's Discord studio builds the tag, previews every style instantly, and copies it to your clipboard.</p>\n\n    <h2>Where timestamps hide in everyday tech</h2>\n    <p>Once you recognize epoch time, you see it everywhere. HTTP cache headers (<code>Expires</code>, <code>Last-Modified</code>), JWT <code>exp</code> claims, OAuth token lifetimes, database <code>created_at</code> columns, file modification times, GPS and telemetry logs, analytics event streams, and certificate validity windows all use it. Log forensics is a major use case: paste a column of epoch values into the batch converter above and an unreadable wall of numbers becomes a readable timeline in seconds \u2014 invaluable when correlating incidents across services that log in different units.</p>\n\n    <h2>Leap seconds: the asterisk on epoch time</h2>\n    <p>Strictly, Unix time <strong>ignores leap seconds</strong>: every day is defined as exactly 86,400 seconds, and the occasional leap second inserted into UTC is simply not counted. That means Unix timestamps drift from true solar time by the accumulated leap seconds (currently 27). For everyday software this is irrelevant, but it matters for astronomy, satellite navigation, and precise scientific measurement, which use TAI or GPS time instead. If you need sub-second legal-time accuracy across leap-second boundaries, convert via a leap-second table rather than raw arithmetic.</p>\n\n    <h2>Best practices for working with epoch time</h2>\n    <ol>\n      <li><strong>Store UTC, display local.</strong> Keep one canonical integer; localize only at render time.</li>\n      <li><strong>Use 64-bit integers</strong> for storage. Never store epoch seconds in a 32-bit column in new systems.</li>\n      <li><strong>Be explicit about units</strong> in APIs \u2014 name fields <code>created_at_ms</code> or document \"epoch seconds\" so consumers never guess.</li>\n      <li><strong>Prefer ISO 8601 strings</strong> (<code>2026-01-01T00:00:00Z</code>) in human-facing APIs; reserve raw integers for machine-to-machine paths.</li>\n      <li><strong>Validate ranges</strong> on input: reject negative values or absurd far-future dates where they make no sense for your domain.</li>\n      <li><strong>Test the 2038 boundary</strong> if your stack touches 32-bit time anywhere, including serialized data and third-party libraries.</li>\n    </ol>\n    <p>Epoch time has survived more than five decades because it is the smallest possible honest representation of \"when\". Whether you are debugging a log, scheduling a Discord event for a worldwide community, or auditing a system for Y2K38, the converter above handles every unit, every direction, and every edge case \u2014 instantly, privately, and free.</p>\n  </article>\n\n  <!-- FAQs -->\n  <div class=\"mt-8\">\n    <h2 class=\"text-xl font-extrabold text-slate-100 mb-4\"><span class=\"prompt\">$</span> faqs <span class=\"text-slate-500\">--6</span></h2>\n    <div class=\"space-y-3\" id=\"faq-list\">\n      <details class=\"faq-item\" open>\n        <summary class=\"px-5 py-4 font-bold text-slate-100 text-sm flex justify-between items-center gap-3\">What is a Unix timestamp?<span class=\"text-phosphor\">+</span></summary>\n        <p class=\"px-5 pb-5 text-sm text-slate-400 leading-relaxed\">A Unix timestamp (epoch time) is the number of seconds since 00:00:00 UTC on 1 January 1970, stored as a plain integer with no timezone. APIs, databases, logs and file systems use it because it is compact, unambiguous and trivial to compare or sort.</p>\n      </details>\n      <details class=\"faq-item\">\n        <summary class=\"px-5 py-4 font-bold text-slate-100 text-sm flex justify-between items-center gap-3\">How do I know if my timestamp is in seconds or milliseconds?<span class=\"text-phosphor\">+</span></summary>\n        <p class=\"px-5 pb-5 text-sm text-slate-400 leading-relaxed\">Count the digits: 10 digits means seconds, 13 means milliseconds, 16 means microseconds and 19 means nanoseconds. Values near 1.7\u20131.8 billion (10 digits) are dates around 2024\u20132027. Epochly auto-detects the unit from digit length automatically.</p>\n      </details>\n      <details class=\"faq-item\">\n        <summary class=\"px-5 py-4 font-bold text-slate-100 text-sm flex justify-between items-center gap-3\">How do I convert an epoch timestamp to a date?<span class=\"text-phosphor\">+</span></summary>\n        <p class=\"px-5 pb-5 text-sm text-slate-400 leading-relaxed\">Paste it into Epochly for an instant conversion to UTC, local time and ISO 8601. In code: JavaScript <code class=\"text-phosphor\">new Date(ts * 1000)</code> for seconds, Python <code class=\"text-phosphor\">datetime.fromtimestamp(ts, tz=timezone.utc)</code>, or Linux <code class=\"text-phosphor\">date -d @ts -u</code>. Always confirm seconds vs milliseconds first.</p>\n      </details>\n      <details class=\"faq-item\">\n        <summary class=\"px-5 py-4 font-bold text-slate-100 text-sm flex justify-between items-center gap-3\">How do Discord timestamp tags work?<span class=\"text-phosphor\">+</span></summary>\n        <p class=\"px-5 pb-5 text-sm text-slate-400 leading-relaxed\">Discord renders <code class=\"text-phosphor\">&lt;t:UNIX_TIMESTAMP:STYLE&gt;</code> in each viewer's own timezone. Styles are t, T, d, D, f, F and R (relative, e.g. \"2 hours ago\"). Use whole seconds, not milliseconds. Epochly generates the tag and previews all seven styles live.</p>\n      </details>\n      <details class=\"faq-item\">\n        <summary class=\"px-5 py-4 font-bold text-slate-100 text-sm flex justify-between items-center gap-3\">What is the Y2K38 problem?<span class=\"text-phosphor\">+</span></summary>\n        <p class=\"px-5 pb-5 text-sm text-slate-400 leading-relaxed\">Signed 32-bit Unix time maxes out at 2,147,483,647 \u2014 03:14:07 UTC on 19 January 2038 \u2014 then overflows to 1901 dates. Modern 64-bit systems are safe, but old embedded devices, databases and file formats may break. Epochly includes a live countdown to the rollover.</p>\n      </details>\n      <details class=\"faq-item\">\n        <summary class=\"px-5 py-4 font-bold text-slate-100 text-sm flex justify-between items-center gap-3\">Why is my converted timestamp off by a few hours?<span class=\"text-phosphor\">+</span></summary>\n        <p class=\"px-5 pb-5 text-sm text-slate-400 leading-relaxed\">Almost always timezone display, not bad data: the timestamp is UTC, but the tool showed it in your local timezone. An offset matching your UTC offset exactly (e.g. 5:30 for IST) confirms this. Compare the UTC output when debugging, and watch for daylight-saving shifts.</p>\n      </details>\n    </div>\n  </div>\n</section>\n\n<!-- ============ FOOTER ============ -->\n<footer class=\"border-t border-dimline\">\n  <div class=\"mx-auto max-w-6xl px-4 sm:px-6 py-8 flex flex-col sm:flex-row items-center justify-between gap-3 text-xs text-slate-500\">\n    <p><span class=\"text-phosphor font-bold\">Epochly_</span> \u00b7 Unix timestamp converter &amp; Discord tag studio</p>\n    <p>All conversions run 100% in your browser. Nothing is uploaded or tracked.</p>\n  </div>\n<p class=\"fx-credit\" style=\"text-align:center;font-size:12.5px;opacity:.62;margin:10px auto 2px;letter-spacing:.01em\">Made by <a href=\"https://fixoraa.tech\" target=\"_blank\" rel=\"noopener\" style=\"color:inherit;font-weight:700;text-decoration:underline;text-underline-offset:2px\">Fixoraa</a></p>\n</footer>\n\n<script id=\"epochly-core\">\n/* EPOCHLY CORE \u2014 pure logic, zero DOM. Shared by the page and the Node test suite. */\nvar Y2K38_TS = 2147483647; // max signed 32-bit unix time -> 2038-01-19T03:14:07Z\nvar DISCORD_STYLES = ['t','T','d','D','f','F','R'];\nvar DISCORD_STYLE_NAMES = { t:'short time', T:'long time', d:'short date', D:'long date', f:'short date/time', F:'long date/time', R:'relative' };\n\nvar FAMOUS_EPOCHS = [\n  { ts: '0',          label: 'Unix epoch \u2014 time begins' },\n  { ts: '1',          label: 'One second after the epoch' },\n  { ts: '1000000000', label: 'Billion-second party' },\n  { ts: '1234567890', label: 'The famous 1234567890' },\n  { ts: '1500000000', label: '1.5 billion seconds' },\n  { ts: '1600000000', label: '1.6 billion seconds' },\n  { ts: '2000000000', label: '2 billion seconds' },\n  { ts: '2147483647', label: 'Y2K38 \u2014 max signed 32-bit' },\n  { ts: '4102444800', label: 'Year 2100 begins' }\n];\n\nfunction detectUnit(raw) {\n  var s = String(raw == null ? '' : raw).trim();\n  if (!/^[+-]?\\d+$/.test(s)) return null;\n  var digits = s.replace(/^[+-]/, '').replace(/^0+/, '') || '0';\n  var len = digits.length;\n  if (len <= 10) return 's';\n  if (len <= 13) return 'ms';\n  if (len <= 16) return 'us';\n  if (len <= 19) return 'ns';\n  return null;\n}\n\nfunction toMsBigInt(raw, unit) {\n  var n = BigInt(String(raw).trim());\n  if (unit === 's')  return n * 1000n;\n  if (unit === 'ms') return n;\n  if (unit === 'us') return n / 1000n;\n  if (unit === 'ns') return n / 1000000n;\n  throw new Error('unknown unit: ' + unit);\n}\n\nfunction pad2(n) { return (n < 10 ? '0' : '') + n; }\n\nfunction formatUTC(msNum) {\n  try {\n    return new Date(msNum).toISOString();\n  } catch (e) { return 'Out of range'; }\n}\n\nfunction formatLocal(msNum) {\n  var d = new Date(msNum);\n  if (isNaN(d.getTime())) return 'Out of range';\n  return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()) + ' ' +\n         pad2(d.getHours()) + ':' + pad2(d.getMinutes()) + ':' + pad2(d.getSeconds());\n}\n\nfunction weekdayName(msNum) {\n  return ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][new Date(msNum).getUTCDay()];\n}\n\nfunction parseTimestamp(raw, unitOverride) {\n  var s = String(raw == null ? '' : raw).trim();\n  if (!/^[+-]?\\d+$/.test(s)) {\n    return { ok: false, raw: s, unit: null, error: 'Not a valid integer timestamp.' };\n  }\n  var unit = (unitOverride && ['s','ms','us','ns'].indexOf(unitOverride) !== -1) ? unitOverride : detectUnit(s);\n  if (!unit) {\n    return { ok: false, raw: s, unit: null, error: 'Could not detect the unit \u2014 too many digits.' };\n  }\n  var ms;\n  try { ms = toMsBigInt(s, unit); }\n  catch (e) { return { ok: false, raw: s, unit: unit, error: 'Number is too large to process.' }; }\n  var msNum = Number(ms);\n  if (!isFinite(msNum) || Math.abs(msNum) > 8.64e15) {\n    return { ok: false, raw: s, unit: unit, error: 'Date is outside the representable range.' };\n  }\n  var iso = formatUTC(msNum);\n  return {\n    ok: true, raw: s, unit: unit, ms: ms, msNum: msNum,\n    iso: iso,\n    utc: iso.replace('T', ' ').replace('Z', ' UTC'),\n    local: formatLocal(msNum),\n    relative: relativeTime(msNum, Date.now()),\n    weekday: weekdayName(msNum)\n  };\n}\n\n/* Date (as ms BigInt) -> all four epoch units, returned as strings (BigInt-safe). */\nfunction dateToAllParts(msBig) {\n  var ms = typeof msBig === 'bigint' ? msBig : BigInt(msBig);\n  return {\n    s:  (ms / 1000n).toString(),\n    ms: ms.toString(),\n    us: (ms * 1000n).toString(),\n    ns: (ms * 1000000n).toString()\n  };\n}\n\nfunction discordTag(tsSec, style) {\n  var t = String(tsSec == null ? '' : tsSec).trim();\n  if (!/^[+-]?\\d+$/.test(t)) throw new Error('Discord tags need whole epoch seconds.');\n  if (DISCORD_STYLES.indexOf(style) === -1) throw new Error('Unknown Discord style: ' + style);\n  return '<t:' + t + ':' + style + '>';\n}\n\nfunction relativeTime(fromMs, toMs) {\n  var diff = Math.round((toMs - fromMs) / 1000);\n  var future = diff > 0;\n  diff = Math.abs(diff);\n  if (diff < 5) return 'just now';\n  var units = [[31557600,'year'],[2592000,'month'],[604800,'week'],[86400,'day'],[3600,'hour'],[60,'minute'],[1,'second']];\n  for (var i = 0; i < units.length; i++) {\n    if (diff >= units[i][0]) {\n      var v = Math.floor(diff / units[i][0]);\n      var str = v + ' ' + units[i][1] + (v > 1 ? 's' : '');\n      return future ? 'in ' + str : str + ' ago';\n    }\n  }\n  return 'just now';\n}\n\n/* Approximate Discord rendering for live preview. tz: IANA name or 'UTC'. */\nfunction discordPreview(msNum, style, nowMs, tz) {\n  var zone = tz || 'UTC';\n  function fmt(opts) {\n    var o = { timeZone: zone };\n    for (var k in opts) o[k] = opts[k];\n    return new Intl.DateTimeFormat('en-US', o).format(new Date(msNum));\n  }\n  switch (style) {\n    case 't': return fmt({ hour: 'numeric', minute: '2-digit' });\n    case 'T': return fmt({ hour: 'numeric', minute: '2-digit', second: '2-digit' });\n    case 'd': return fmt({ month: 'numeric', day: 'numeric', year: 'numeric' });\n    case 'D': return fmt({ month: 'long', day: 'numeric', year: 'numeric' });\n    case 'f': return fmt({ month: 'long', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' });\n    case 'F': return fmt({ weekday: 'long', month: 'long', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' });\n    case 'R': return relativeTime(msNum, nowMs == null ? Date.now() : nowMs);\n    default: throw new Error('Unknown Discord style: ' + style);\n  }\n}\n\n/* Batch: one timestamp per line -> converted rows. */\nfunction batchConvert(text) {\n  var rows = [];\n  String(text == null ? '' : text).split(/\\r?\\n/).forEach(function (line, i) {\n    var trimmed = line.trim();\n    if (!trimmed) return;\n    var m = trimmed.match(/[+-]?\\d+/);\n    if (!m) { rows.push({ line: i + 1, raw: '', unit: null, ok: false, error: 'No number found on this line.' }); return; }\n    var p = parseTimestamp(m[0], null);\n    rows.push({ line: i + 1, raw: m[0], unit: p.unit, ok: p.ok, iso: p.iso || null,\n                utc: p.utc || null, local: p.local || null, error: p.error || null });\n  });\n  return rows;\n}\n\nfunction y2k38Remaining(nowMs) {\n  var targetMs = Y2K38_TS * 1000;\n  var rem = targetMs - nowMs;\n  if (rem <= 0) return { passed: true, remainingMs: 0, days: 0, hours: 0, minutes: 0, seconds: 0 };\n  var totalSec = Math.floor(rem / 1000);\n  return {\n    passed: false,\n    remainingMs: rem,\n    days: Math.floor(totalSec / 86400),\n    hours: Math.floor(totalSec % 86400 / 3600),\n    minutes: Math.floor(totalSec % 3600 / 60),\n    seconds: totalSec % 60\n  };\n}\n\nfunction y2k38Progress(nowMs) {\n  var start = 0, end = Y2K38_TS * 1000;\n  if (nowMs <= start) return 0;\n  if (nowMs >= end) return 100;\n  return (nowMs - start) / (end - start) * 100;\n}\n</script>\n\n<script>\n(function () {\n  'use strict';\n  var $ = function (id) { return document.getElementById(id); };\n  var UNIT_LABELS = { s: 'seconds', ms: 'milliseconds', us: 'microseconds', ns: 'nanoseconds' };\n\n  function show(el, msg) { el.textContent = msg; el.classList.remove('hidden'); }\n  function hide(el) { el.classList.add('hidden'); }\n\n  function copyText(text, btn) {\n    function done() {\n      if (!btn) return;\n      var old = btn.textContent;\n      btn.textContent = 'COPIED \u2713'; btn.classList.add('copied');\n      setTimeout(function () { btn.textContent = old; btn.classList.remove('copied'); }, 1400);\n    }\n    if (navigator.clipboard && navigator.clipboard.writeText) {\n      navigator.clipboard.writeText(text).then(done, done);\n    } else {\n      var ta = document.createElement('textarea');\n      ta.value = text; document.body.appendChild(ta); ta.select();\n      try { document.execCommand('copy'); } catch (e) {}\n      document.body.removeChild(ta); done();\n    }\n  }\n  document.querySelectorAll('[data-copy-target]').forEach(function (btn) {\n    btn.addEventListener('click', function () {\n      var t = $(btn.getAttribute('data-copy-target'));\n      var txt = t ? (t.textContent || '').trim() : '';\n      if (txt && txt !== '\u2014') copyText(txt, btn);\n    });\n  });\n\n  /* ---------- live hero clock ---------- */\n  function tickHero() {\n    var now = Date.now();\n    $('hero-seconds').textContent = Math.floor(now / 1000);\n    $('hero-ms').textContent = now;\n    $('hero-utc').textContent = new Date(now).toISOString().replace('T', ' ').slice(0, 19) + ' UTC';\n    var d = new Date(now);\n    $('hero-local').textContent = d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()) + ' ' +\n      pad2(d.getHours()) + ':' + pad2(d.getMinutes()) + ':' + pad2(d.getSeconds());\n  }\n  tickHero(); setInterval(tickHero, 1000);\n\n  /* ---------- pane A: timestamp -> date ---------- */\n  var tsInput = $('ts-input'), unitOverride = $('unit-override');\n  function runTsConvert() {\n    var raw = tsInput.value.trim();\n    hide($('ts-error'));\n    if (!raw) {\n      $('ts-results').classList.add('opacity-40');\n      $('unit-badge').textContent = 'auto: \u2014';\n      ['r-utc','r-local','r-iso','r-rel','r-day'].forEach(function (id) { $(id).textContent = '\u2014'; });\n      return;\n    }\n    var ov = unitOverride.value === 'auto' ? null : unitOverride.value;\n    var p = parseTimestamp(raw, ov);\n    $('unit-badge').textContent = p.unit ? ('auto: ' + UNIT_LABELS[p.unit]) : 'auto: ?';\n    if (!p.ok) { show($('ts-error'), '\u26a0 ' + p.error); $('ts-results').classList.add('opacity-40'); return; }\n    $('ts-results').classList.remove('opacity-40');\n    $('r-utc').textContent = p.utc;\n    $('r-local').textContent = p.local;\n    $('r-iso').textContent = p.iso;\n    $('r-rel').textContent = p.relative;\n    $('r-day').textContent = p.weekday;\n  }\n  $('ts-convert').addEventListener('click', runTsConvert);\n  tsInput.addEventListener('input', runTsConvert);\n  unitOverride.addEventListener('change', runTsConvert);\n  $('ts-now').addEventListener('click', function () { tsInput.value = String(Math.floor(Date.now() / 1000)); runTsConvert(); });\n  $('ts-clear').addEventListener('click', function () { tsInput.value = ''; runTsConvert(); });\n\n  /* ---------- pane B: date -> timestamp ---------- */\n  var dtInput = $('dt-input'), interpretUTC = false;\n  function setTz(which) {\n    interpretUTC = (which === 'utc');\n    $('tz-utc').classList.toggle('active', interpretUTC);\n    $('tz-local').classList.toggle('active', !interpretUTC);\n    runDtConvert();\n  }\n  $('tz-local').addEventListener('click', function () { setTz('local'); });\n  $('tz-utc').addEventListener('click', function () { setTz('utc'); });\n\n  function inputToMs() {\n    var v = dtInput.value;\n    if (!v) return null;\n    var parts = v.split('T');\n    var dp = parts[0].split('-').map(Number), tp = (parts[1] || '00:00:00').split(':').map(Number);\n    if (interpretUTC) return Date.UTC(dp[0], dp[1] - 1, dp[2], tp[0] || 0, tp[1] || 0, tp[2] || 0);\n    return new Date(dp[0], dp[1] - 1, dp[2], tp[0] || 0, tp[1] || 0, tp[2] || 0).getTime();\n  }\n  function runDtConvert() {\n    hide($('dt-error'));\n    var ms = inputToMs();\n    if (ms == null || isNaN(ms)) {\n      $('dt-results').classList.add('opacity-40');\n      ['o-s','o-ms','o-us','o-ns'].forEach(function (id) { $(id).textContent = '\u2014'; });\n      return;\n    }\n    var parts = dateToAllParts(BigInt(ms));\n    $('dt-results').classList.remove('opacity-40');\n    $('o-s').textContent = parts.s; $('o-ms').textContent = parts.ms;\n    $('o-us').textContent = parts.us; $('o-ns').textContent = parts.ns;\n  }\n  $('dt-convert').addEventListener('click', runDtConvert);\n  dtInput.addEventListener('input', runDtConvert);\n  $('dt-now').addEventListener('click', function () {\n    var d = new Date();\n    function p2(n){ return (n<10?'0':'')+n; }\n    dtInput.value = d.getFullYear() + '-' + p2(d.getMonth()+1) + '-' + p2(d.getDate()) + 'T' + p2(d.getHours()) + ':' + p2(d.getMinutes()) + ':' + p2(d.getSeconds());\n    runDtConvert();\n  });\n\n  /* ---------- batch mode ---------- */\n  var BATCH_SAMPLE = '1767225600\\n1767225600000\\n1699999999123456\\n1699999999123456789\\n0\\n-86400';\n  $('batch-sample').addEventListener('click', function () { $('batch-input').value = BATCH_SAMPLE; runBatch(); });\n  $('batch-clear').addEventListener('click', function () {\n    $('batch-input').value = '';\n    $('batch-body').innerHTML = '<tr><td colspan=\"5\" class=\"!text-slate-600 !text-center py-6\">No rows yet \u2014 paste timestamps above and hit CONVERT ALL.</td></tr>';\n    $('batch-copy').classList.add('hidden'); hide($('batch-error'));\n  });\n  function esc(s) { return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }\n  function runBatch() {\n    hide($('batch-error'));\n    var rows = batchConvert($('batch-input').value);\n    if (!rows.length) {\n      show($('batch-error'), '\u26a0 Paste at least one timestamp first (try LOAD SAMPLE).');\n      return;\n    }\n    var html = rows.map(function (r) {\n      if (!r.ok) return '<tr><td class=\"text-slate-600\">' + r.line + '</td><td class=\"tick text-red-400\">' + esc(r.raw || '\u2014') + '</td><td colspan=\"3\" class=\"text-red-400/80\">\u26a0 ' + esc(r.error) + '</td></tr>';\n      return '<tr><td class=\"text-slate-600\">' + r.line + '</td><td class=\"tick text-phosphor\">' + esc(r.raw) + '</td>' +\n        '<td class=\"text-amberx\">' + esc(r.unit) + '</td><td class=\"tick\">' + esc(r.utc) + '</td>' +\n        '<td class=\"tick text-slate-500\">' + esc(r.iso) + '</td></tr>';\n    }).join('');\n    $('batch-body').innerHTML = html;\n    $('batch-copy').classList.remove('hidden');\n  }\n  $('batch-run').addEventListener('click', runBatch);\n  $('batch-copy').addEventListener('click', function (e) {\n    var rows = batchConvert($('batch-input').value).filter(function (r) { return r.ok; });\n    var tsv = 'input\\tunit\\tutc\\tiso\\n' + rows.map(function (r) { return r.raw + '\\t' + r.unit + '\\t' + r.utc + '\\t' + r.iso; }).join('\\n');\n    copyText(tsv, e.currentTarget);\n  });\n\n  /* ---------- discord studio ---------- */\n  var dcInput = $('dc-input');\n  function dcMs() {\n    var v = dcInput.value;\n    if (!v) return null;\n    var parts = v.split('T');\n    var dp = parts[0].split('-').map(Number), tp = (parts[1] || '00:00:00').split(':').map(Number);\n    return new Date(dp[0], dp[1] - 1, dp[2], tp[0] || 0, tp[1] || 0, tp[2] || 0).getTime();\n  }\n  function dcStyle() {\n    var el = document.querySelector('input[name=\"dc-style\"]:checked');\n    return el ? el.value : 'f';\n  }\n  function runDiscord() {\n    hide($('dc-error'));\n    var ms = dcMs();\n    if (ms == null || isNaN(ms)) {\n      $('dc-tag').textContent = '<t:\u2026:' + dcStyle() + '>';\n      $('dc-preview').textContent = '\u2014';\n      return;\n    }\n    var sec = Math.floor(ms / 1000);\n    var style = dcStyle();\n    try {\n      $('dc-tag').textContent = discordTag(sec, style);\n    } catch (e) { show($('dc-error'), '\u26a0 ' + e.message); return; }\n    var tz = Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC';\n    $('dc-preview').textContent = discordPreview(ms, style, Date.now(), tz);\n    var now = Date.now();\n    $('dc-all-styles').innerHTML = DISCORD_STYLES.map(function (s) {\n      return '<div class=\"flex justify-between gap-2\"><span class=\"text-amberx font-bold w-16\">:' + s + ' <span class=\"text-slate-600 font-normal\">' + DISCORD_STYLE_NAMES[s] + '</span></span><span class=\"text-slate-300 text-right\">' + esc(discordPreview(ms, s, now, tz)) + '</span></div>';\n    }).join('');\n    var d = new Date(ms);\n    $('dc-preview-time').textContent = 'Today at ' + pad2(d.getHours()) + ':' + pad2(d.getMinutes());\n  }\n  dcInput.addEventListener('input', runDiscord);\n  document.querySelectorAll('input[name=\"dc-style\"]').forEach(function (r) { r.addEventListener('change', runDiscord); });\n  $('dc-now').addEventListener('click', function () {\n    var d = new Date();\n    function p2(n){ return (n<10?'0':'')+n; }\n    dcInput.value = d.getFullYear() + '-' + p2(d.getMonth()+1) + '-' + p2(d.getDate()) + 'T' + p2(d.getHours()) + ':' + p2(d.getMinutes()) + ':' + p2(d.getSeconds());\n    runDiscord();\n  });\n  $('dc-copy').addEventListener('click', function (e) {\n    var txt = $('dc-tag').textContent.trim();\n    if (txt.indexOf('\u2026') !== -1) { show($('dc-error'), '\u26a0 Pick a date & time first.'); return; }\n    copyText(txt, e.currentTarget);\n  });\n\n  /* ---------- y2k38 countdown ---------- */\n  function tickCd() {\n    var r = y2k38Remaining(Date.now());\n    if (r.passed) {\n      ['cd-d','cd-h','cd-m','cd-s'].forEach(function (id) { $(id).textContent = '0'; });\n      $('cd-pct').textContent = '100%';\n      $('cd-bar').style.width = '100%';\n      return;\n    }\n    $('cd-d').textContent = r.days.toLocaleString('en-US');\n    $('cd-h').textContent = pad2(r.hours);\n    $('cd-m').textContent = pad2(r.minutes);\n    $('cd-s').textContent = pad2(r.seconds);\n    var pct = y2k38Progress(Date.now());\n    $('cd-pct').textContent = pct.toFixed(4) + '%';\n    $('cd-bar').style.width = pct + '%';\n  }\n  tickCd(); setInterval(tickCd, 1000);\n\n  /* ---------- famous epochs ---------- */\n  $('famous-body').innerHTML = FAMOUS_EPOCHS.map(function (e) {\n    var p = parseTimestamp(e.ts, null);\n    return '<tr class=\"cursor-pointer\" data-ts=\"' + esc(e.ts) + '\" title=\"Load into converter\">' +\n      '<td class=\"tick text-phosphor\">' + esc(e.ts) + '</td>' +\n      '<td class=\"tick\">' + esc(p.ok ? p.utc : '\u2014') + '</td>' +\n      '<td>' + esc(e.label) + '</td></tr>';\n  }).join('');\n  document.querySelectorAll('#famous-body tr').forEach(function (tr) {\n    tr.addEventListener('click', function () {\n      tsInput.value = tr.getAttribute('data-ts');\n      runTsConvert();\n      tsInput.scrollIntoView({ behavior: 'smooth', block: 'center' });\n      tsInput.focus({ preventScroll: true });\n    });\n  });\n\n  /* deep-link: #ts=<value> loads the converter */\n  try {\n    var m = location.hash.match(/#ts=([+-]?\\d+)/);\n    if (m) { tsInput.value = m[1]; runTsConvert(); }\n  } catch (e) {}\n})();\n</script>\n</body>\n</html>\n";
export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname !== "/" && url.pathname !== "/index.html") {
      return new Response("Not found", { status: 404 });
    }
    return new Response(HTML, {
      headers: { "content-type": "text/html;charset=UTF-8" }
    });
  }
};